import{_ as n,c as i,o as a,ah as t}from"./chunks/framework.oAolcYhj.js";const r="/Qonnectra-docs/pr-14/images/manual/teil-a/login_start.jpg",s="/Qonnectra-docs/pr-14/images/manual/teil-a/login_start_detail.jpg",l="/Qonnectra-docs/pr-14/images/manual/teil-a/login_navigation.jpg",d="/Qonnectra-docs/pr-14/images/manual/teil-a/login_sidebar.jpg",o="/Qonnectra-docs/pr-14/images/manual/teil-a/login_settings.jpg",h="/Qonnectra-docs/pr-14/images/manual/teil-a/login_header.jpg",u="/Qonnectra-docs/pr-14/images/manual/teil-a/dashboard_project.jpg",c="/Qonnectra-docs/pr-14/images/manual/teil-a/dashboard_project_detail.jpg",_=JSON.parse('{"title":"1. Erste Schritte","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-a-anwenderhandbuch/01-erste-schritte.md","filePath":"manual/teil-a-anwenderhandbuch/01-erste-schritte.md"}'),m={name:"manual/teil-a-anwenderhandbuch/01-erste-schritte.md"};function g(b,e,p,f,k,w){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="_1-erste-schritte" tabindex="-1">1. Erste Schritte <a class="header-anchor" href="#_1-erste-schritte" aria-label="Permalink to &quot;1. Erste Schritte&quot;">​</a></h1><p>Dieses Kapitel führt Sie in die Anwendung ein: Anmeldung, Aufbau der Oberfläche und die Einstellungen, die Sie gleich am Anfang brauchen.</p><h2 id="_1-1-anmelden-und-abmelden" tabindex="-1">1.1 Anmelden und abmelden <a class="header-anchor" href="#_1-1-anmelden-und-abmelden" aria-label="Permalink to &quot;1.1 Anmelden und abmelden&quot;">​</a></h2><p>Qonnectra wird über einen Webbrowser bedient; eine Installation auf Ihrem Rechner ist nicht nötig. Die Adresse zur Anmeldung erhalten Sie von Ihrer Organisation oder zuständigen Verwaltung. Melden Sie sich mit Benutzernamen und Passwort an; „Login“ oder die Eingabetaste bringt Sie zum Dashboard.</p><p class="img-row"><img src="'+r+'" alt="Screenshot Anmeldeseite mit dem Anmeldeformular auf der rechten Seite" data-zoomable="true"><img src="'+s+'" alt="Screenshot Ausschnittvergrößerung des Anmeldeformulars mit den Feldern „Benutzername“ und „Passwort“ und der Schaltfläche „Login“" data-zoomable="true"></p><p>Zum Abmelden klicken Sie in der Kopfzeile rechts auf „Abmelden“.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Stimmen Benutzername oder Passwort nicht, erscheint am unteren Bildschirmrand kurz die Meldung „Fehler beim Anmelden“ und Sie bleiben auf der Anmeldeseite. Prüfen Sie in diesem Fall die Groß- und Kleinschreibung.</p></div><h3 id="_1-1-1-noch-keine-zugangsdaten" tabindex="-1">1.1.1 Noch keine Zugangsdaten? <a class="header-anchor" href="#_1-1-1-noch-keine-zugangsdaten" aria-label="Permalink to &quot;1.1.1 Noch keine Zugangsdaten?&quot;">​</a></h3><p>Falls Sie noch keine Zugangsdaten erhalten haben, wenden Sie sich bitte an Ihre Projektleitung oder Ihre Administration. Ein Benutzerkonto kann dort für Sie angelegt werden.</p><h3 id="_1-1-2-passwort-vergessen" tabindex="-1">1.1.2 Passwort vergessen? <a class="header-anchor" href="#_1-1-2-passwort-vergessen" aria-label="Permalink to &quot;1.1.2 Passwort vergessen?&quot;">​</a></h3><p>Derzeit gibt es keine „Passwort vergessen“-Funktion im System. Wenn Sie Ihr Passwort nicht mehr wissen, hilft Ihnen Ihre Projektleitung oder Administration weiter. Dort kann das Passwort zurückgesetzt oder ein neues vergeben werden.</p><h2 id="_1-2-aufbau-der-oberflache" tabindex="-1">1.2 Aufbau der Oberfläche <a class="header-anchor" href="#_1-2-aufbau-der-oberflache" aria-label="Permalink to &quot;1.2 Aufbau der Oberfläche&quot;">​</a></h2><p>Nach der Anmeldung befinden Sie sich auf dem Dashboard. Die Bedienoberfläche ist immer gleich aufgebaut und besteht aus drei Bereichen: der <strong>Navigationsleiste</strong> am linken Rand, der <strong>Kopfzeile</strong> am oberen Rand und der <strong>Inhaltsfläche</strong> in der Mitte.</p><p><img src="'+l+'" alt="Screenshot Startbildschirm mit Hervorhebung der einzelnen Bestandteile der App" class="big no-border" data-zoomable="true"></p><h3 id="_1-2-1-navigationsleiste" tabindex="-1">1.2.1 Navigationsleiste <a class="header-anchor" href="#_1-2-1-navigationsleiste" aria-label="Permalink to &quot;1.2.1 Navigationsleiste&quot;">​</a></h3><p>Über die Navigationsleiste am linken Rand wechseln Sie zu allen verfügbaren Ansichten; sie bleibt beim Arbeiten immer sichtbar. Die Einträge sind nach Themen gruppiert:</p><ul><li>„Info“ – „Dashboard“ (Startansicht, siehe Kapitel <a href="./04-dashboard.html">Dashboard</a>) und „Karte“ (siehe Kapitel <a href="./05-karte.html">Karte</a>)</li><li>„Funktionen“ – „Störungsanalyse“, „Nachverdichtung“, „Leitungsauskunft“ und „Wertermittlung“: Auswertungen und Verfahren, die auf den dokumentierten Daten aufbauen</li><li>„Rohr“ – „Verwaltung“ (siehe Kapitel <a href="./10-rohrverwaltung.html">Rohrverwaltung</a>), „Zuordnung“ (siehe Kapitel <a href="./11-rohrzuordnung.html">Rohrzuordnung</a>), „Verzweigung“ und „Mikrorohre“</li><li>„Kabel“ – „Netzschema“ und „Faserweg“</li><li>„Gebäude“ – „Adressen“</li></ul><p><img src="'+d+'" alt="Screenshot Dashboard mit Hervorhebung der Navigationsleiste am linken Rand" data-zoomable="true"></p><p>Am Fuß der Leiste steht unter der Überschrift „System“ der Eintrag „Einstellungen“ (siehe Kapitel <a href="./17-einstellungen.html">Einstellungen</a>) und, wenn Ihre Installation eine Adresse für dieses Handbuch hinterlegt hat, „Dokumentation“. Mit den entsprechenden Rechten erscheint dort zusätzlich „Logs“ mit den Systemprotokollen.</p><p><img src="'+o+'" alt="Screenshot Dashboard mit Hervorhebung des Fußbereichs „System“ mit „Logs“ und „Einstellungen“ unten links" data-zoomable="true"></p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Wenn der Fußbereich „System“ nicht zu sehen ist, scrollen Sie in der Navigationsleiste nach unten.</p></div><p>Die Breite der Leiste stellen Sie unter „Einstellungen“ ein: „Erweitert“ zeigt die Beschriftungen, „Eingeklappt“ nur die Symbole.</p><h3 id="_1-2-2-kopfzeile" tabindex="-1">1.2.2 Kopfzeile <a class="header-anchor" href="#_1-2-2-kopfzeile" aria-label="Permalink to &quot;1.2.2 Kopfzeile&quot;">​</a></h3><p>Oben links in der Anwendung befindet sich das Projektauswahl-Menü, siehe Abschnitt <a href="#_1-3-projekt-auswahlen-und-wechseln">Projekt auswählen und wechseln</a>. Oben rechts in der Kopfzeile finden Sie die Angaben und Schaltflächen, die in Abschnitt <a href="#_1-4-sprache-hell-und-dunkelmodus-versionsanzeige-und-dokumentation">Sprache, Hell- und Dunkelmodus, Versionsanzeige und Dokumentation</a> beschrieben sind.</p><p><img src="'+h+'" alt="Screenshot Dashboard mit Hervorhebung der Kopfzeile am oberen Rand" data-zoomable="true"></p><h3 id="_1-2-3-inhaltsflache" tabindex="-1">1.2.3 Inhaltsfläche <a class="header-anchor" href="#_1-2-3-inhaltsflache" aria-label="Permalink to &quot;1.2.3 Inhaltsfläche&quot;">​</a></h3><p>In der zentralen Inhaltsfläche werden alle projektbezogenen Informationen angezeigt: Statistiken, Listen, Karten usw. Welche Inhalte sichtbar sind, hängt vom gewählten Projekt (oben links in der Kopfzeile), dem gewählten Navigationseintrag (linke Navigationsleiste) und ggf. von dem gewählten Reiter (meist unterhalb der Kopfzeile) ab.</p><h2 id="_1-3-projekt-auswahlen-und-wechseln" tabindex="-1">1.3 Projekt auswählen und wechseln <a class="header-anchor" href="#_1-3-projekt-auswahlen-und-wechseln" aria-label="Permalink to &quot;1.3 Projekt auswählen und wechseln&quot;">​</a></h2><p>Alle Daten in Qonnectra gehören zu einem <strong>Projekt</strong>. Welches Projekt gilt, wählen Sie oben links in der Kopfzeile; die Auswahl gilt für die gesamte Anwendung und bleibt beim Wechsel in eine andere Ansicht erhalten. Kennzahlen, Karteninhalte und Listen zeigen deshalb immer nur den Bestand des ausgewählten Projekts.</p><p>Die Projektauswahl ist eine Kombination aus Eingabefeld und Auswahlliste: Über den Pfeil am rechten Rand öffnen Sie die Liste aller für Sie freigegebenen Projekte, über eine Eingabe in das Feld schränken Sie die Liste auf passende Namen ein. Mit dem Klick auf einen Eintrag wechseln Sie das Projekt; alle angezeigten Inhalte aktualisieren sich daraufhin automatisch.</p><p class="img-row"><img src="'+u+'" alt="Screenshot Dashboard mit Hervorhebung der Projektauswahl oben links in der Kopfzeile" data-zoomable="true"><img src="'+c+'" alt="Screenshot Ausschnittvergrößerung der geöffneten Projektliste in der Kopfzeile mit dem hervorgehobenen Eintrag „Testprojekt“" data-zoomable="true"></p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Die Eingabe im Feld allein wählt nichts aus – erst der Klick auf einen Eintrag der Liste wechselt das Projekt. Solange kein Projekt gewählt ist, bleiben alle Kennzahlen auf Null und die Diagramme zeigen „Keine Daten verfügbar“.</p></div><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Sind für Ihr Benutzerkonto keine Projekte freigegeben, erscheint anstelle des Feldes der Hinweis „Keine Projekte verfügbar“.</p></div><p>In den Kartenansichten steht neben der Projektauswahl zusätzlich die Schaltfläche „Alle Projekte anzeigen“, mit der Sie die Beschränkung auf das gewählte Projekt vorübergehend aufheben.</p><h2 id="_1-4-sprache-hell-und-dunkelmodus-versionsanzeige-und-dokumentation" tabindex="-1">1.4 Sprache, Hell- und Dunkelmodus, Versionsanzeige und Dokumentation <a class="header-anchor" href="#_1-4-sprache-hell-und-dunkelmodus-versionsanzeige-und-dokumentation" aria-label="Permalink to &quot;1.4 Sprache, Hell- und Dunkelmodus, Versionsanzeige und Dokumentation&quot;">​</a></h2><p>Oben rechts in der Kopfzeile finden Sie:</p><ul><li>die aktuelle Softwareversion, z. B. „v1.7.0“ – geben Sie diese Angabe mit an, wenn Sie einen Fehler bei Ihrem Systemadministrator melden</li><li>die Spracheinstellung: Deutsch („DE“) oder Englisch („EN“)</li><li>einen Verweis auf das Projekt bei GitHub, in dem Qonnectra entwickelt wird</li><li>„Hell-/Dunkelmodus umschalten“</li><li>„Abmelden“</li></ul><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Wenn Ihre Installation eine Adresse für dieses Handbuch hinterlegt hat, erscheint zusätzlich ein Buchsymbol („Dokumentation“), das das Handbuch in einem neuen Tab öffnet.</p></div><h2 id="_1-5-navigationsleiste-anpassen" tabindex="-1">1.5 Navigationsleiste anpassen <a class="header-anchor" href="#_1-5-navigationsleiste-anpassen" aria-label="Permalink to &quot;1.5 Navigationsleiste anpassen&quot;">​</a></h2><p>Ein Klick auf einen Gruppennamen – etwa „Funktionen“ – klappt die Gruppe zu und wieder auf. Einträge, die Sie nicht benötigen, können Sie dauerhaft ausblenden:</p><ol><li>Klicken Sie oben rechts neben dem Schriftzug „Qonnectra“ auf das Symbol mit den Schiebereglern („Seitenleiste anpassen“).</li><li>Klicken Sie neben einem Eintrag auf „Ausblenden“. Über „Einblenden“ holen Sie ihn zurück, „Seitenleiste zurücksetzen“ stellt alle Einträge und Gruppen wieder her.</li><li>Beenden Sie die Anpassung über dasselbe Symbol („Fertig“).</li></ol><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Zugeklappte Gruppen und ausgeblendete Einträge merkt sich nur der Browser, in dem Sie sie eingestellt haben – an einem anderen Rechner sehen Sie wieder die vollständige Navigationsleiste.</p></div><p>Der Fußbereich „System“ lässt sich nicht ausblenden.</p><h2 id="_1-6-bedienung-auf-tablet-und-smartphone" tabindex="-1">1.6 Bedienung auf Tablet und Smartphone <a class="header-anchor" href="#_1-6-bedienung-auf-tablet-und-smartphone" aria-label="Permalink to &quot;1.6 Bedienung auf Tablet und Smartphone&quot;">​</a></h2><p><em>Die Dokumentation zu diesem Abschnitt ist noch in Arbeit.</em></p><h2 id="_1-7-warum-manche-menupunkte-fehlen-berechtigungen" tabindex="-1">1.7 Warum manche Menüpunkte fehlen: Berechtigungen <a class="header-anchor" href="#_1-7-warum-manche-menupunkte-fehlen-berechtigungen" aria-label="Permalink to &quot;1.7 Warum manche Menüpunkte fehlen: Berechtigungen&quot;">​</a></h2><p>Welche Menüpunkte Sie sehen und was Sie darin ändern dürfen, hängt von den Rechten Ihres Benutzerkontos ab. Fehlt ein in diesem Handbuch genannter Bereich, ist er für Ihr Konto nicht freigegeben – wenden Sie sich in diesem Fall an Ihre Administration.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Die Rechte wirken nicht nur auf die Navigationsleiste: Auch innerhalb einer Ansicht kann eine Aktion an fehlenden Rechten scheitern. In diesem Fall erscheint eine Fehlermeldung und die Daten bleiben unverändert.</p></div>',48)])])}const z=n(m,[["render",g]]);export{_ as __pageData,z as default};
